    Definition W0 (a : Z) : Prop := zwin (sp - 192) sp a \/ zwin (ds + 256) (ds + 260) a \/ zwin (ds + 136) (ds + 144) a.

    Lemma zero_tail : forall R3 M3, m = 0 ->
      stores_in W0 M M3 -> fld SEGS M3 (ds + 136) 8 0 -> fld SEGS M3 (ds + 256) 4 32 ->
      getr R3 10%bv = Z_to_bv 64 ds -> getr R3 1%bv = Z_to_bv 64 ret -> kept R R3 ->
      srealizes SEGS (cfg fx R3 PC_RETPC M3 model) K.
Proof using AC RRND MI ST DN fx A s R M model sp ret S ds err len p m B K m0 pp0 hm0 fl fill CB HS Ha2 DI0 ABOVE Hp SRCOK RDM BUD POST.
